 let h=`<div class="svkg">${["W","F","M"].map(f=>{const q=asvSt(ss.filter(s=>s.f===f));return kpi(FQ[f]+" active sites",q.p,"%",90,true,null,q.n+" sites \u00b7 "+q.met+" of "+q.due+" visits due")}).join("")}${(()=>{const q=asvSt(ss);return kpi("All active sites",q.p,"%",90,true,null,q.n+" sites \u00b7 "+q.met+" of "+q.due+" visits due")})()}</div>`;
 const grp=S.d<0?DATA.D.map((n,i)=>({n,f:s=>s.d===i})):[...new Set(ss.map(s=>s.t))].sort().map(t=>({n:t.replace(/\b\w/g,c=>c.toUpperCase()).toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()),f:s=>s.t===t}));
 const rows=grp.map(g=>{const q=["W","F","M"].map(f=>asvSt(ss.filter(s=>s.f===f&&g.f(s)))),a=asvSt(ss.filter(g.f));return[g.n,...q.flatMap(x=>[x.n,x.due,x.met,asvc(x.p)]),a.n,asvc(a.p)]});
 const tq=["W","F","M"].map(f=>asvSt(ss.filter(s=>s.f===f))),ta=asvSt(ss);rows.push([{v:nm+" total"},...tq.flatMap(x=>[x.n,x.due,x.met,asvc(x.p)]),ta.n,asvc(ta.p)]);
 h+=card("Active site visits by frequency, 2026","A visit is counted when the site was visited at least once in the period it was due (week, fortnight or month). Green is 90% or more, amber 75 to 89%, red below 75%. Data to "+plab("W",A.lastp.W)+", "+plab("F",A.lastp.F)+" and "+plab("M",A.lastp.M)+".",tbl([S.d<0?"District":"Tehsil","Weekly sites","Due","Visited","Weekly %","Fortnightly sites","Due","Visited","Fortnightly %","Monthly sites","Due","Visited","Monthly %","All sites","All %"],rows,"sc"));
 const tab=`<div class="svsrc"><b>Frequency</b><div class="svseg">${["W","F","M"].map(f=>`<button type="button" class="svfo ${S.af===f?"on":""}" data-f="${f}">${FQ[f]}</button>`).join("")}</div></div>`;
