function pNotes(){return card("How the indicators are calculated","",`<ul class="svn"><li><b>NPAFP rate.</b> AFP cases with final classification 3 (non-polio AFP), per 100,000 children under 15. The current year is annualised: cases to date \u00d7 365 \u00f7 days elapsed. Benchmark 3 per 100,000.</li><li><b>True AFP rate.</b> Cases whose provisional diagnosis is G61.0, G37.3, B34.1 or T80, per 100,000 children under 15.</li><li><b>GBS rate.</b> Provisional diagnosis G61 or GBS, per 100,000 under 15.</li><li><b>Stool adequacy.</b> AFP cases marked ADEQ, % of cases with an adequacy recorded. Benchmark 80%.</li><li><b>Notified within 7 days.</b> Date of notification minus date of onset is 0 to 7 days. Benchmark 80%.</li><li><b>Investigated within 48 hours.</b> Date of investigation minus date of notification is 0 to 2 days. Benchmark 80%.</li><li><b>NPEV and Sabin-like isolation.</b> Counted per stool specimen from the lab file (AFP cases and contacts). NPEV = enterovirus result 1. Sabin-like = poliovirus type 1, 2 or 3 result 2. Benchmark for NPEV 10%.</li><li><b>Environmental surveillance.</b> Results of ES samples from the regular ES sites in the national ES file (Hangu, Karak, Kohat and Kurram). A sample is NPEV positive when NPEV was isolated, Sabin-like positive when any Sabin-like poliovirus was isolated. ES NPEV benchmark: at least 50% of samples.</li><li><b>Active site visits.</b> Weekly, fortnightly and monthly active sites are checked against the 2026 visit trackers. A visit is met when the site was visited at least once in the period it was due. Green is 90% or more.</li><li><b>Population.</b> Under-15 population by district and tehsil from the indicator workbook. District totals use the district figures, tehsil rows use the tehsil figures.</li><li><b>Dates.</b> Cases are grouped by year and month of paralysis onset. Data is as of ${asof().toLocaleDateString("en-GB",{day:"numeric",month:"long",year:"numeric"})}, the latest entry in the AFP file.</li></ul>`)+card("Data sources","",`<p class="svs">AFP.REC and AFPLAB.REC (national AFP surveillance database, Khyber Pakhtunkhwa), filtered to Hangu, Karak, Kohat, Kurram and Orakzai, onset 2022 to 2026, the national ES results file, the reviewed ES site list (June 2026) and the 2026 active site visit trackers. No names, addresses or exact dates of birth are held in this dashboard.</p>`)}
const TABS=[["ov","Overview"],["ind","Indicators"],["ev","EV and SL isolation"],["epi","Epidemiology"],["con","Contact analysis"],["map","Maps"],["es","Environmental surveillance"],["asv","Active site visits"],["glob","Global update"],["ppt","Presentation"],["notes","Definitions"]];
const HERO={ov:["Divisional overview","The headline surveillance indicators against their benchmarks."],ind:["Surveillance indicators","NPAFP, True AFP, GBS, stool adequacy, notification and investigation timeliness by district."],ev:["EV and SL isolation","Non-polio enterovirus and Sabin-like isolation from AFP and contact stool specimens."],epi:["Epidemiology","Cases by month, age, OPV status, health seeking behaviour and union council."],con:["Contact analysis","At which contact with the health system the AFP case was notified."],map:["Maps","Case spots, silent union councils and the reporting network."],es:["Environmental surveillance","ES sites, their catchment UCs and the sewage sample results."],asv:["Active site visits","Weekly, fortnightly and monthly visit compliance of active surveillance sites."],glob:["Global polio update","Wild and vaccine-derived poliovirus cases worldwide."],ppt:["Presentation","Download the surveillance update PowerPoint for the division or a district."],notes:["Definitions","How each indicator is calculated."]};
