 document.querySelectorAll(".svsf").forEach(b=>b.onclick=()=>{S.es=+b.dataset.s<0?null:+b.dataset.s;render()});document.querySelectorAll(".svso").forEach(b=>b.onclick=()=>{S.src=b.dataset.s;render()});document.querySelectorAll(".svbo").forEach(b=>b.onclick=()=>{S.pit=b.dataset.p==="1";render()});document.querySelectorAll(".svuo").forEach(b=>b.onclick=()=>{S.uz=+b.dataset.u;render()});document.querySelectorAll(".svfo").forEach(b=>b.onclick=()=>{S.af=b.dataset.f;render()});
